// Blockscout source verification for the Levier mainnet contracts (Robinhood Chain 4663).
// Run in the browser console on https://robinhoodchain.blockscout.com (any page), so the
// requests go out from your browser session, which passes the explorer bot check.
// It adds a file picker to the page: select the 9 *.standard-input.json files from
// packages/contracts/deployments/mainnet-4663-verification/, then it verifies all 19 contracts.
(() => {
  const COMPILER = "v0.8.24+commit.e11b9ed9";
  const CONTRACTS = [
    {
      "role": "registry",
      "name": "LevierMarketRegistry",
      "address": "0x67bAEC5f4f7d7Bf608ce7468020cE7ADc8003788",
      "args": "000000000000000000000000d09d9c87ecfe008b4d6d3cebead25103c16d9a7c"
    },
    {
      "role": "lendingRouter",
      "name": "LevierRouter",
      "address": "0xD85c786F22BEF47EEb682C3317487230c994353a",
      "args": ""
    },
    {
      "role": "autoProtect",
      "name": "AutoProtectModule",
      "address": "0x6F6478E0df9A167a1CF8e0167f4363C77946637f",
      "args": "000000000000000000000000d09d9c87ecfe008b4d6d3cebead25103c16d9a7c"
    },
    {
      "role": "shortRouter",
      "name": "ShortRouter",
      "address": "0x848Bc0505531C698Be77986E34143CaC57241f3b",
      "args": "000000000000000000000000d09d9c87ecfe008b4d6d3cebead25103c16d9a7c"
    },
    {
      "role": "vault",
      "name": "LevierVault",
      "address": "0xa834e4FeB0DaCBF4F05b64136E87D0fd6536Ff09",
      "args": ""
    },
    {
      "role": "leverageRouter",
      "name": "LeverageRouter",
      "address": "0x8717177eb656513B127FbC8Db77a98B390920963",
      "args": "000000000000000000000000d09d9c87ecfe008b4d6d3cebead25103c16d9a7c"
    },
    {
      "role": "oracle",
      "name": "VerifiedFeedOracle",
      "address": "0x970d03b53411b13B1F66E3540C668C9931D911e7",
      "args": ""
    },
    {
      "role": "long-tsla",
      "name": "LevierPair",
      "address": "0xE96F794DB31eDBD052277fFA0f28BB5048Ca6f0A",
      "args": ""
    },
    {
      "role": "short-tsla",
      "name": "LevierPair",
      "address": "0x797d6DCfEd44A80746C1BDd791cBAa94eE954d93",
      "args": ""
    },
    {
      "role": "long-amzn",
      "name": "LevierPair",
      "address": "0xA4A33F284Ff717a06c85A7a2f01aE8218D380b52",
      "args": ""
    },
    {
      "role": "short-amzn",
      "name": "LevierPair",
      "address": "0x2aA54d74Fbd6893D02886C62b99dc91b40b9BeAd",
      "args": ""
    },
    {
      "role": "long-pltr",
      "name": "LevierPair",
      "address": "0xD9E8B8BC6B5eb0a8265cAC743aE558Cee116C894",
      "args": ""
    },
    {
      "role": "short-pltr",
      "name": "LevierPair",
      "address": "0x2E8913E306102a474378fdb342F1e4e47dC76A70",
      "args": ""
    },
    {
      "role": "long-amd",
      "name": "LevierPair",
      "address": "0x7295e668FF2Aec83588c14C462EFa03423a39b1D",
      "args": ""
    },
    {
      "role": "short-amd",
      "name": "LevierPair",
      "address": "0xeDF91101a19e489F198A20BDE8e7944A02B538Fa",
      "args": ""
    },
    {
      "role": "margin-tsla",
      "name": "MarginRouter",
      "address": "0x5d97eBB1Ab376649827346444DD140e5A7aC6829",
      "args": ""
    },
    {
      "role": "margin-amzn",
      "name": "MarginRouter",
      "address": "0xAd73561a14C1914E5e11DC9bA961191E3d9C33DD",
      "args": ""
    },
    {
      "role": "margin-pltr",
      "name": "MarginRouter",
      "address": "0xd7a7dff16D46917a93ED886240177B404A57eaA0",
      "args": ""
    },
    {
      "role": "margin-amd",
      "name": "MarginRouter",
      "address": "0x62CC46E61CFa0ca4E86D31ebEA76728A1fDc7758",
      "args": ""
    }
  ];
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const api = (path) => location.origin + "/api/v2/smart-contracts/" + path;
  // The address endpoint carries is_verified; the smart-contract endpoint carries the source
  // once verified. Either one is enough.
  async function isVerified(address) {
    const a = await fetch(location.origin + "/api/v2/addresses/" + address);
    if (a.ok && (await a.json()).is_verified) return true;
    const r = await fetch(api(address));
    if (!r.ok) return false;
    const d = await r.json();
    return Boolean(d.is_verified || d.is_fully_verified || d.verified_at || d.source_code);
  }
  async function verify(c, file) {
    const form = new FormData();
    form.append("compiler_version", COMPILER);
    form.append("contract_name", c.name);
    form.append("license_type", "mit");
    form.append("autodetect_constructor_args", c.args ? "false" : "true");
    if (c.args) form.append("constructor_args", c.args);
    form.append("files[0]", file, file.name);
    const r = await fetch(api(c.address + "/verification/via/standard-input"), { method: "POST", body: form });
    return r.status + " " + (await r.text()).slice(0, 160);
  }
  async function run(files) {
    const byName = {};
    for (const f of files) byName[f.name.replace(".standard-input.json", "")] = f;
    const missing = [...new Set(CONTRACTS.map((c) => c.name))].filter((n) => !byName[n]);
    if (missing.length) return console.error("Missing files:", missing.join(", "));
    console.log("Verifying " + CONTRACTS.length + " Levier contracts on " + location.host);
    for (const c of CONTRACTS) {
      const label = c.role.padEnd(15) + c.name.padEnd(21) + c.address;
      await sleep(1500);
      if (await isVerified(c.address)) { console.log(label + "  already verified"); continue; }
      // Blockscout rate-limits anonymous API use (HTTP 429): back off and retry.
      let response = await verify(c, byName[c.name]);
      for (let i = 0; i < 5 && response.startsWith("429"); i++) {
        console.log(label + "  rate limited, retrying in 20 s");
        await sleep(20000);
        response = await verify(c, byName[c.name]);
      }
      console.log(label + "  submitted: " + response);
      if (!response.startsWith("200")) { console.warn(label + "  submission rejected, skipping wait"); continue; }
      let ok = false;
      for (let i = 0; i < 12 && !ok; i++) { await sleep(5000); ok = await isVerified(c.address); }
      console.log(label + (ok ? "  VERIFIED" : "  not verified yet (check the page later)"));
    }
    let done = 0;
    for (const c of CONTRACTS) if (await isVerified(c.address)) done++;
    console.log(done + " of " + CONTRACTS.length + " Levier contracts verified on Blockscout.");
  }
  const input = document.createElement("input");
  input.type = "file"; input.multiple = true; input.accept = ".json";
  input.style.cssText = "position:fixed;top:12px;right:12px;z-index:99999;background:#fff;padding:8px;border:2px solid #000";
  input.onchange = () => { input.remove(); run([...input.files]); };
  document.body.appendChild(input);
  console.log("Select the 9 *.standard-input.json files with the picker at the top right of the page.");
})();
